        spread: 1 - 0.3 * w,                 // 実弾の散布
        oppEvade: (1 - 0.15 * w) * (1 - 0.10 * a), // 相手の回避率に掛ける (命中)
        rxRange: 1 + 0.17 * s,               // 受信の最大距離
