        const n = _spriteTry[k] || 0;
        if (n >= 10) continue;
        _spriteTry[k] = n + 1;
        const ni = new Image();
        ni.src = SPRITE_FILES[k] + '?v=' + SPRITE_VER + '&r=' + (n + 1);
