    const hf = document.getElementById('ss-hp-fill'), ht = document.getElementById('ss-hp-text');
    if (hf) { hf.style.width = hpP + '%'; hf.style.backgroundColor = col; } if (ht) { ht.textContent = hpP + '%'; ht.style.color = col; }
