                        tg.addColorStop(0,   `rgba(${ecp.core},${0.88 * tpz * ecp.a})`);
                        tg.addColorStop(0.4, `rgba(${ecp.mid},${0.48 * tpz * ecp.a})`);
                        tg.addColorStop(1,   'rgba(0,10,40,0)');
