// ============================================================
// GEN配分スライダー (ゼロサム: 合計100% — ENG/WEP/SEN のみ)
// AI は独立スライダー (0〜100% 自由設定、GEN合計に含まない)
// ============================================================
const GEN_KEYS = ['engine', 'weapons', 'sensors'];

function updateGenTotal() {
    const total = GEN_KEYS.reduce((sum, k) => sum + genAlloc[k], 0);
    const totalEl = document.getElementById('gen-total');
    if (totalEl) {
        totalEl.textContent = `計${total}%`;
        totalEl.style.color = total === 100 ? '#00ffaa' : '#ff4d4d';
    }
    // プレイヤー速度をエンジン配分で決定
    if (player) player.generatorOutput = genAlloc.engine;
}

GEN_KEYS.forEach(key => {
    const slider = document.getElementById(`gen-${key}`);
    if (!slider) return;
    slider.addEventListener('input', e => {
        const newVal = parseInt(e.target.value);
        const oldVal = genAlloc[key];
        const delta = newVal - oldVal;
        genAlloc[key] = newVal;

        // ゼロサム: 他のスライダーを按分調整
        const others = GEN_KEYS.filter(k => k !== key);
        const otherTotal = others.reduce((sum, k) => sum + genAlloc[k], 0);
        if (delta !== 0) {
            let remaining = -delta;
            if (otherTotal > 0) {
                // 按分配分 (クリップ後の実変化量でremainingを追跡)
                others.forEach((k, i) => {
                    const prevVal = genAlloc[k];
                    if (i === others.length - 1) {
                        genAlloc[k] = Math.min(100, Math.max(0, genAlloc[k] + remaining));
                    } else {
                        const adj = Math.round(remaining * (genAlloc[k] / otherTotal));
                        genAlloc[k] = Math.min(100, Math.max(0, genAlloc[k] + adj));
                        remaining -= (genAlloc[k] - prevVal); // クリップ後の実変化量を引く
                    }
                    const el = document.getElementById(`gen-${k}`);
                    const valEl = document.getElementById(`gen-${k}-val`);
                    if (el) el.value = genAlloc[k];
                    if (valEl) valEl.textContent = genAlloc[k] + '%';
                });
            } else {
                // 他が全て0 → 最後のスライダーに全て割り当て
                const last = others[others.length - 1];
                genAlloc[last] = Math.min(100, Math.max(0, genAlloc[last] + remaining));
                const el = document.getElementById(`gen-${last}`);
                const valEl = document.getElementById(`gen-${last}-val`);
                if (el) el.value = genAlloc[last];
                if (valEl) valEl.textContent = genAlloc[last] + '%';
            }
            // 端数誤差補正: 合計が100になるよう最終調整
            const total = GEN_KEYS.reduce((sum, k) => sum + genAlloc[k], 0);
            if (total !== 100) {
                const diff = 100 - total;
                // 最も大きい配分のキーで調整
                const adjustKey = others.reduce((best, k) => genAlloc[k] > genAlloc[best] ? k : best, others[0]);
                genAlloc[adjustKey] = Math.min(100, Math.max(0, genAlloc[adjustKey] + diff));
                const el = document.getElementById(`gen-${adjustKey}`);
                const valEl = document.getElementById(`gen-${adjustKey}-val`);
                if (el) el.value = genAlloc[adjustKey];
                if (valEl) valEl.textContent = genAlloc[adjustKey] + '%';
            }
        }

        const valEl = document.getElementById(`gen-${key}-val`);
        if (valEl) valEl.textContent = newVal + '%';
        updateGenTotal();
    });
});
updateGenTotal();

// 第15弾: GEN配分の「重点」プリセット (第39弾: 定義はファイル先頭の GEN_FOCUS — 解析重視を追加)
// ═══ 第36弾 (オーナー合意): GENの詳細設定 (MT) — 各ゲイン0〜200% (100%=均等)。合計の上限なし。
// 100%を超えた分は、その系統のシグネチャが ゲイン² 倍 (200%で4倍)。複数上げればそれぞれの系統が漏れる。AT (重点4つ) は従来どおり
const GEN_MT_BASE = { engine: GEN_FOCUS.balance.engine, weapons: GEN_FOCUS.balance.weapons, sensors: GEN_FOCUS.balance.sensors, ai: 50 };
let genMT = null; // null=AT / {engine,weapons,sensors,ai} = 0..2
function mtOver(k) { if (!genMT) return 1; const g = genMT[k]; return g > 1 ? g * g : 1; }
function setGenMT(k, g) {
    if (!genMT) genMT = { engine: genAlloc.engine / GEN_MT_BASE.engine, weapons: genAlloc.weapons / GEN_MT_BASE.weapons, sensors: genAlloc.sensors / GEN_MT_BASE.sensors, ai: genAlloc.ai / GEN_MT_BASE.ai }; // 第59弾: 今の重点の配分から始める (旧: 全部1に戻っていた)
    genMT[k] = Math.max(0, Math.min(2, g));
    _applyGenMT();
}
function _applyGenMT() {
    if (!genMT) return;
    for (const k of ['engine', 'weapons', 'sensors', 'ai']) genAlloc[k] = GEN_MT_BASE[k] * genMT[k];
    _pfx = null; // 第39弾: 航行モードの効果を作り直す
    for (const k of ['sensor', 'weapon', 'engine']) aiPrecision[k] = GEN_FOCUS.balance.prec[k];
    if (player) player.generatorOutput = genAlloc.engine;
    document.querySelectorAll('.gd-focus-btn, .focus-btn').forEach(b => b.classList.remove('active'));
    document.getElementById('btn-focus-mt')?.classList.add('active');
    _syncMTPanel();
}
// ═══ 第59弾 (オーナー): AIの解析力をその場で調整 — 帯域バーの右隣のトグル。低 → 標準 → 高 → 最大 (MT の AI ゲイン 0.5/1/1.5/2) ═══
//   高いほど 解析・識別が速い (×1.4まで)・助言が速く細かい・視界外の命中の観測が正確。代わりに演算の電磁波・熱が漏れる (ゲイン²)。低いと漏れは減るが 解析が遅く 誤判断が増える
const AI_LEVELS = [{ g: 0.5, jp: '低' }, { g: 0.75, jp: 'やや低' }, { g: 1, jp: '標準' }, { g: 1.5, jp: '高' }, { g: 2, jp: '最大' }]; // 第90弾: 5段階
function aiLevelIdx() { const r = genAlloc.ai / 50; let bi = 2, bd = 9; AI_LEVELS.forEach((l, i) => { const d = Math.abs(l.g - r); if (d < bd) { bd = d; bi = i; } }); return bi; }
function cycleAiLevel() {
    const n = (aiLevelIdx() + 1) % AI_LEVELS.length;
    setGenMT('ai', AI_LEVELS[n].g);
    if (typeof playSound === 'function') sfxUI('ui_level_' + (n + 1));
    logMessage('AI: 解析力 ' + AI_LEVELS[n].jp + (n >= 2 ? ' — 演算の電磁波・熱が漏れる (×' + (AI_LEVELS[n].g * AI_LEVELS[n].g).toFixed(1) + ')' : n === 0 ? ' — 漏れは減るが 解析が遅く 誤判断が増える' : ' — 均等'), 'system-msg');
    _syncAiBtn(true);
}
let _aiBtnLast = '';
function _syncAiBtn(force) {
    const b = document.getElementById('btn-ai-level'); if (!b) return;
    const i = aiLevelIdx(), key = i + ':' + (comDemo ? 1 : 0);
    if (!force && key === _aiBtnLast) return; _aiBtnLast = key;
    b.querySelectorAll('.ai-seg i').forEach((e, k) => e.classList.toggle('on', k <= i));
    b.querySelector('.ai-val').textContent = AI_LEVELS[i].jp;
    b.classList.toggle('hot', i >= 3); b.classList.toggle('low', i <= 1);
}
document.getElementById('btn-ai-level')?.addEventListener('click', (e) => { e.stopPropagation(); if (!comDemo) cycleAiLevel(); });
function _syncMTPanel() {
    const pn = document.getElementById('mt-panel');
    if (!pn) return;
    const g = genMT || { engine: 1, weapons: 1, sensors: 1, ai: 1 };
    pn.querySelectorAll('.mt-row').forEach(r => {
        const k = r.dataset.k, v = Math.round(g[k] * 100);
        const inp = r.querySelector('input'); if (inp && +inp.value !== v) inp.value = v;
        const lb = r.querySelector('.mt-val'); if (lb) { lb.textContent = v + '%'; lb.className = 'mt-val' + (v > 100 ? ' hot' : v < 100 ? ' low' : ''); }
    });
    const sg = document.getElementById('mt-sig');
    if (sg) {
        const parts = [];
        const nm = { engine: '推進の熱・光・電磁波', weapons: '兵装の熱・電磁波', sensors: '探知の電磁波', ai: 'AIの電磁波・熱' };
        for (const k in nm) { const m = g[k] > 1 ? g[k] * g[k] : 1; if (m > 1.001) parts.push(nm[k] + '×' + m.toFixed(1)); }
        sg.textContent = parts.length ? '漏れ: ' + parts.join(' / ') : '漏れ: 均等と同じ';
        sg.classList.toggle('hot', parts.length > 0);
    }
}
function openMTPanel(on) {
    const pn = document.getElementById('mt-panel');
    if (!pn) return;
    const show = on === undefined ? pn.classList.contains('hidden') : !!on;
    pn.classList.toggle('hidden', !show);
    if (show) { if (!genMT) setGenMT('engine', 1); else _syncMTPanel(); }
}
(() => {
    const pn = document.getElementById('mt-panel');
    if (!pn) return;
    pn.querySelectorAll('.mt-row').forEach(r => r.querySelector('input')?.addEventListener('input', (e) => setGenMT(r.dataset.k, +e.target.value / 100)));
    document.getElementById('mt-close')?.addEventListener('click', () => openMTPanel(false));
    document.getElementById('mt-maxall')?.addEventListener('click', () => { for (const k of ['engine', 'weapons', 'sensors', 'ai']) setGenMT(k, 2); });
    document.getElementById('mt-reset')?.addEventListener('click', () => { for (const k of ['engine', 'weapons', 'sensors', 'ai']) setGenMT(k, 1); });
    document.getElementById('mt-at')?.addEventListener('click', () => { openMTPanel(false); setGenFocus('balance'); });
    document.getElementById('btn-focus-mt')?.addEventListener('click', () => openMTPanel(true));
})();
function setGenFocus(key, quiet) {
    const f = GEN_FOCUS[key];
    if (!f) return;
    genMT = null; document.getElementById('btn-focus-mt')?.classList.remove('active'); // 第36弾: ATに戻す
    genFocusKey = key; _pfx = null;
    genAlloc.ai = f.ai; // 第39弾: 解析重視は AI 80
    for (const k of GEN_KEYS) {
        genAlloc[k] = f[k];
        const el = document.getElementById(`gen-${k}`), v = document.getElementById(`gen-${k}-val`);
        if (el) el.value = f[k];
        if (v) v.textContent = f[k] + '%';
    }
    for (const k of ['sensor', 'weapon', 'engine']) {
        aiPrecision[k] = f.prec[k];
        const el = document.getElementById(`aiprec-${k}`), v = document.getElementById(`aiprec-${k}-val`);
        if (el) el.value = f.prec[k];
        if (v) v.textContent = f.prec[k] + '%';
    }
    updateGenTotal();
    if (player) player.generatorOutput = genAlloc.engine;
    document.querySelectorAll('.gd-focus-btn, .focus-btn').forEach(b => b.classList.toggle('active', b.dataset.focus === key));
    if (!quiet) sfxUI('ui_focus_change');
}
document.querySelectorAll('.gd-focus-btn').forEach(b => b.addEventListener('click', (e) => { e.stopPropagation(); setGenFocus(b.dataset.focus); }));

// AI スライダー: GENゼロサムとは独立して 0〜100% 自由設定
const aiSlider = document.getElementById('gen-ai');
const aiValEl  = document.getElementById('gen-ai-val');
if (aiSlider) {
    aiSlider.addEventListener('input', e => {
        genAlloc.ai = parseInt(e.target.value);
        if (aiValEl) aiValEl.textContent = genAlloc.ai + '%';
    });
}

// AI精度配分 (§3-2): 解析/命中/回避 のゼロサム3スライダー (GENと同方式)
const AIPREC_KEYS = ['sensor', 'weapon', 'engine'];
AIPREC_KEYS.forEach(key => {
    const slider = document.getElementById(`aiprec-${key}`);
    if (!slider) return;
    slider.addEventListener('input', e => {
        const newVal = parseInt(e.target.value);
        const delta = newVal - aiPrecision[key];
        aiPrecision[key] = newVal;
        const others = AIPREC_KEYS.filter(k => k !== key);
        const otherTotal = others.reduce((s, k) => s + aiPrecision[k], 0);
        if (delta !== 0) {
            let remaining = -delta;
            if (otherTotal > 0) {
                others.forEach((k, i) => {
                    const prev = aiPrecision[k];
                    if (i === others.length - 1) aiPrecision[k] = Math.min(100, Math.max(0, aiPrecision[k] + remaining));
                    else { const adj = Math.round(remaining * (aiPrecision[k] / otherTotal)); aiPrecision[k] = Math.min(100, Math.max(0, aiPrecision[k] + adj)); remaining -= (aiPrecision[k] - prev); }
                });
            } else {
                const last = others[others.length - 1];
                aiPrecision[last] = Math.min(100, Math.max(0, aiPrecision[last] + remaining));
            }
            const total = AIPREC_KEYS.reduce((s, k) => s + aiPrecision[k], 0);
            if (total !== 100) {
                const adjustKey = others.reduce((b, k) => aiPrecision[k] > aiPrecision[b] ? k : b, others[0]);
                aiPrecision[adjustKey] = Math.min(100, Math.max(0, aiPrecision[adjustKey] + (100 - total)));
            }
        }
        AIPREC_KEYS.forEach(k => {
            const el = document.getElementById(`aiprec-${k}`);
            const valEl = document.getElementById(`aiprec-${k}-val`);
            if (el) el.value = aiPrecision[k];
            if (valEl) valEl.textContent = aiPrecision[k] + '%';
        });
    });
});

