            ctx.beginPath(); ctx.moveTo(mn.x - r * 1.5, mn.y); ctx.lineTo(mn.x + r * 1.5, mn.y); ctx.moveTo(mn.x, mn.y - r * 1.5); ctx.lineTo(mn.x, mn.y + r * 1.5); ctx.stroke();
