    const arc = WEAPON_FIRE_ARC[wType] || (Math.PI / 4);
    if (Math.abs(_angDiff(ang, player.angle)) > arc) { logMessage(`WEP: 射角外 — 艦首±${Math.round(arc * 180 / Math.PI)}°以内に向けてから発射`, 'warning-msg'); return; }
