    for (const t of SHIP_DRONES[gameState.shipType] || []) cargo.stock[t] = lo[t] || 0;
    if (player) player.kineticAmmo = Math.min(player.kineticMaxAmmo || KINETIC_MAG, cargo.ammoK);
