    const capOk = DRONE_SPEC[type].item || activeDeployCount() < (CARGO_CAP[gameState.shipType] || 0);
    return capOk && ((cargo.stock[type] || 0) > 0 || (!cargo.asm && cargo.mat >= DRONE_SPEC[type].mat));
