    if (on('it_sos') && F.n('sos') > 1 && st >= 0.5 && F.exposure < 1 && F.quietF > 5400 && F.cd('sosF', 120)) return go('sos', '長く気配が無い → 行く手に偽SOSを置いて誘う', 'sosF');
