            ctx.globalAlpha = 0.35; ctx.strokeStyle = d._q >= DRONE_LINK_WEAK ? '#ffaa44' : '#ff5555';
            ctx.lineWidth = 1 * zc; ctx.setLineDash([10 * zc, 10 * zc]);
